import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

if (!process.env.AI_TRADING_DATA_DIR) {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ai-trading-test-'));
  process.env.AI_TRADING_DATA_DIR = tempDir;
  process.env.AI_TRADING_DB_PATH = path.join(tempDir, 'trading.db');

  process.once('exit', () => {
    try {
      fs.rmSync(tempDir, { recursive: true, force: true });
    } catch {}
  });
}

process.env.NODE_ENV = 'test';

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { indodax } from '../src/services/indodax/index.js';
import { TradingEngine, PositionRecord, tradingEngine } from '../src/services/trading/index.js';
import { checkMaxDrawdown, capAllocationByEquityPercent } from '../src/services/trading/riskGuard.js';
import { db, getSetting, setSetting } from '../src/db/index.js';

const engine = new TradingEngine();

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function insertLivePosition(base: string, amount: number, price: number): PositionRecord {
  const pos: PositionRecord = {
    id: `pos_sh_${Math.random().toString(36).slice(2, 9)}`,
    symbol: `${base}idr`,
    base_currency: 'idr',
    traded_currency: base,
    side: 'buy',
    entry_price: price,
    current_price: price,
    amount,
    initial_cost_idr: amount * price,
    highest_price: price,
    trailing_stop_price: price * 0.975,
    take_profit_step: 0,
    status: 'open',
    opened_at: Date.now() - 3600000,
    closed_at: null,
    pnl_idr: 0,
    pnl_percent: 0,
    exit_reason: null,
    mode: 'live',
  };

  db.prepare(`
    INSERT INTO positions (
      id, symbol, base_currency, traded_currency, side, entry_price, current_price,
      amount, initial_cost_idr, highest_price, trailing_stop_price, take_profit_step,
      status, opened_at, mode
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).run(
    pos.id, pos.symbol, pos.base_currency, pos.traded_currency, pos.side,
    pos.entry_price, pos.current_price, pos.amount, pos.initial_cost_idr,
    pos.highest_price, pos.trailing_stop_price, pos.take_profit_step,
    pos.status, pos.opened_at, pos.mode
  );

  return pos;
}

function cleanupPosition(id: string) {
  db.prepare('DELETE FROM positions WHERE id = ?').run(id);
  db.prepare('DELETE FROM trades_history WHERE position_id = ?').run(id);
  db.prepare('DELETE FROM order_intents WHERE position_id = ?').run(id);
}

interface RecordedOrder {
  symbol: string;
  side: string;
  type: string;
  quantity?: number;
  price?: number;
  quoteOrderQty?: number;
  newClientOrderId?: string;
}

/**
 * Swaps createOrder/waitForOrderFill with a scripted exchange. Each script
 * entry describes the fill an order of a given type should produce.
 */
function mockExchange(scripts: Array<{ type: string; executedQty: number; price: number }>) {
  const calls: RecordedOrder[] = [];
  const originalCreate = indodax.createOrder;
  const originalWait = indodax.waitForOrderFill;
  let scriptIndex = 0;

  indodax.createOrder = (async (options: any) => {
    calls.push({ ...options });
    const script = scripts[Math.min(scriptIndex, scripts.length - 1)];
    scriptIndex++;
    return {
      orderId: 9000 + scriptIndex,
      status: script.executedQty > 0 ? 'FILLED' : 'NEW',
      executedQty: String(script.executedQty),
      quoteQty: String(script.executedQty * script.price),
      avgPrice: String(script.price),
    };
  }) as any;

  indodax.waitForOrderFill = (async (_symbol: string, _orderId: string, rawResponse?: any) => {
    return indodax.extractOrderFill(rawResponse ?? {}, {});
  }) as any;

  return {
    calls,
    restore() {
      indodax.createOrder = originalCreate;
      indodax.waitForOrderFill = originalWait;
    },
  };
}

// ---------------------------------------------------------------------------
// Pure gates
// ---------------------------------------------------------------------------

describe('Max Drawdown Kill Switch Gate (pure)', () => {
  test('passes when equity is near the peak', () => {
    const gate = checkMaxDrawdown(950_000, 1_000_000, 15, 0);
    assert.equal(gate.passed, true);
  });

  test('fails when drawdown from peak exceeds the limit', () => {
    const gate = checkMaxDrawdown(800_000, 1_000_000, 15, 0);
    assert.equal(gate.passed, false);
    assert.ok(gate.reason.includes('20.00%'));
  });

  test('fails when equity is below the absolute floor', () => {
    const gate = checkMaxDrawdown(4_000_000, 5_000_000, 90, 5_000_000);
    assert.equal(gate.passed, false);
    assert.ok(gate.reason.includes('floor'));
  });

  test('is disabled when both limits are zero', () => {
    const gate = checkMaxDrawdown(1, 1_000_000, 0, 0);
    assert.equal(gate.passed, true);
  });

  test('handles an unset peak (fresh install) without triggering', () => {
    const gate = checkMaxDrawdown(10_000_000, 0, 15, 0);
    assert.equal(gate.passed, true);
  });
});

describe('Equity-Percent Allocation Cap (pure)', () => {
  test('caps allocation above the configured percent of equity', () => {
    const r = capAllocationByEquityPercent(500_000, 1_000_000, 20);
    assert.equal(r.capped, true);
    assert.equal(r.allocationIdr, 200_000);
  });

  test('passes allocation through when below the cap', () => {
    const r = capAllocationByEquityPercent(100_000, 1_000_000, 20);
    assert.equal(r.capped, false);
    assert.equal(r.allocationIdr, 100_000);
  });

  test('is disabled when percent is zero', () => {
    const r = capAllocationByEquityPercent(999_999, 1_000, 0);
    assert.equal(r.capped, false);
    assert.equal(r.allocationIdr, 999_999);
  });
});

// ---------------------------------------------------------------------------
// Floored exit execution
// ---------------------------------------------------------------------------

describe('Floored Limit Exit (live sell execution)', () => {
  test('fills fully on the exchange through a single LIMIT sell at the floor price', async () => {
    const pos = insertLivePosition('flooret', 10, 100_000);
    const mock = mockExchange([{ type: 'LIMIT', executedQty: 10, price: 97_500 }]);
    setSetting('exit_floor_limit_enabled', '1');

    try {
      const result = await engine.executeSell(pos, 10, 100_000, 'Trailing Stop', { floorPrice: 97_500 });
      assert.equal(result.ok, true);
      assert.equal(result.filledAmount, 10);
      assert.equal(mock.calls.length, 1, 'full limit fill must not spawn a market order');
      assert.equal(mock.calls[0].type, 'LIMIT');
      assert.equal(mock.calls[0].side, 'SELL');
      assert.equal(mock.calls[0].price, 97_500, 'limit price must equal the floor');
      assert.ok(mock.calls[0].newClientOrderId, 'clientOrderId must travel with the order');

      // Intent journaled and resolved
      const intent = db.prepare('SELECT * FROM order_intents WHERE client_order_id = ?').get(mock.calls[0].newClientOrderId) as any;
      assert.ok(intent, 'intent row must exist for the clientOrderId');
      assert.equal(intent.state, 'resolved');
    } finally {
      mock.restore();
      cleanupPosition(pos.id);
    }
  });

  test('sells the remainder via MARKET when the limit partially fills, combining both fills', async () => {
    const pos = insertLivePosition('flopart', 10, 100_000);
    const mock = mockExchange([
      { type: 'LIMIT', executedQty: 4, price: 97_500 },
      { type: 'MARKET', executedQty: 6, price: 97_000 },
    ]);

    try {
      const result = await engine.executeSell(pos, 10, 100_000, 'Trailing Stop', { floorPrice: 97_500 });
      assert.equal(result.ok, true);
      assert.equal(result.filledAmount, 10);
      assert.equal(mock.calls.length, 2);
      assert.equal(mock.calls[0].type, 'LIMIT');
      assert.equal(mock.calls[1].type, 'MARKET');
      assert.equal(mock.calls[1].quantity, 6, 'market remainder must be the unfilled part');

      // Combined proceeds: 4*97500 + 6*97000 = 972000 → avg 97200
      assert.equal(result.proceedsIdr, 972_000);
      assert.equal(result.averagePrice, 97_200);

      const history = db.prepare("SELECT amount, total_idr FROM trades_history WHERE position_id = ? AND type = 'SELL'").get(pos.id) as any;
      assert.ok(history);
      assert.equal(history.amount, 10);
      assert.equal(history.total_idr, 972_000);
    } finally {
      mock.restore();
      cleanupPosition(pos.id);
    }
  });

  test('flags a dust remainder below the exchange minimum as unprotected and still records the limit fill', async () => {
    const pos = insertLivePosition('flodust', 10, 100_000);
    const mock = mockExchange([
      { type: 'LIMIT', executedQty: 9.95, price: 97_500 },
      { type: 'MARKET', executedQty: 0, price: 97_000 }, // must never be called
    ]);

    try {
      const result = await engine.executeSell(pos, 10, 100_000, 'Trailing Stop', { floorPrice: 97_500 });
      assert.equal(result.ok, true);
      assert.equal(result.filledAmount, 9.95);
      assert.equal(result.fullyFilled, false);
      assert.equal(mock.calls.length, 1, 'dust remainder must not be sent as a market order');

      const history = db.prepare("SELECT amount FROM trades_history WHERE position_id = ? AND type = 'SELL'").get(pos.id) as any;
      assert.ok(history, 'the limit fill must still be recorded in trades_history');
      assert.equal(history.amount, 9.95);

      const row = db.prepare('SELECT amount, unprotected_since FROM positions WHERE id = ?').get(pos.id) as any;
      assert.ok(row.unprotected_since, 'dust position must be flagged unprotected');
    } finally {
      mock.restore();
      cleanupPosition(pos.id);
    }
  });

  test('closePosition refuses to retry a position whose total value is below the exchange minimum', async () => {
    const pos = insertLivePosition('flodust2', 0.05, 100_000); // Rp 5.000 < min Rp 10.000
    const mock = mockExchange([]);

    try {
      const sold = await engine.closePosition(pos, 100_000, 'Trailing Stop');
      assert.equal(sold, false);
      assert.equal(mock.calls.length, 0, 'no order may be sent for an unsellable dust position');

      const row = db.prepare('SELECT status, unprotected_since FROM positions WHERE id = ?').get(pos.id) as any;
      assert.equal(row.status, 'open');
      assert.ok(row.unprotected_since);
    } finally {
      mock.restore();
      cleanupPosition(pos.id);
    }
  });

  test('falls back to a blind MARKET sell when the limit placement throws (behavior parity with the old path)', async () => {
    const pos = insertLivePosition('flofall', 10, 100_000);
    const calls: RecordedOrder[] = [];
    const originalCreate = indodax.createOrder;
    const originalWait = indodax.waitForOrderFill;

    indodax.createOrder = (async (options: any) => {
      calls.push({ ...options });
      if (options.type === 'LIMIT') throw new Error('simulated limit rejection');
      return { orderId: 9500, status: 'FILLED', executedQty: '10', quoteQty: '970000', avgPrice: '97000' };
    }) as any;
    indodax.waitForOrderFill = (async (_s: string, _o: string, raw?: any) => indodax.extractOrderFill(raw ?? {}, {})) as any;

    try {
      const result = await engine.executeSell(pos, 10, 100_000, 'Trailing Stop', { floorPrice: 97_500 });
      assert.equal(result.ok, true);
      assert.equal(result.filledAmount, 10);
      assert.equal(mockExchangeLength(calls), 2);
      assert.equal(calls[1].type, 'MARKET');
    } finally {
      indodax.createOrder = originalCreate;
      indodax.waitForOrderFill = originalWait;
      cleanupPosition(pos.id);
    }
  });

  function mockExchangeLength(calls: RecordedOrder[]) {
    return calls.length;
  }
});

// ---------------------------------------------------------------------------
// Order intent journal & crash recovery
// ---------------------------------------------------------------------------

describe('Order Intent Journal (idempotency & crash recovery)', () => {
  // Isolate from leftovers of earlier suites in the same process: the
  // reconciler scans the whole journal, so every test here starts clean.
  function sealExistingIntents() {
    db.prepare("UPDATE order_intents SET state = 'resolved', resolved_at = ? WHERE state IN ('sent', 'ack')").run(Date.now());
  }

  test('live buy records an intent before sending, acks with the exchange id, and resolves after recording', async () => {
    sealExistingIntents();
    const originalAccount = indodax.getAccountInfo;
    const calls: RecordedOrder[] = [];
    const originalCreate = indodax.createOrder;
    const originalWait = indodax.waitForOrderFill;

    indodax.getAccountInfo = (async () => ({
      canTrade: true,
      canWithdraw: false,
      accountType: 'spot',
      balances: [{ asset: 'IDR', free: '10000000', locked: '0' }],
    })) as any;
    indodax.createOrder = (async (options: any) => {
      calls.push({ ...options });
      return { orderId: 777, status: 'FILLED', executedQty: '100', quoteQty: '100000', avgPrice: '1000' };
    }) as any;
    indodax.waitForOrderFill = (async (_s: string, _o: string, raw?: any) => indodax.extractOrderFill(raw ?? {}, {})) as any;

    try {
      const ok = await engine.executeBuy('itstbuy', 1000, 100, 100_000, 'live', 'test entry');
      assert.equal(ok, true);
      assert.equal(calls.length, 1);
      assert.ok(calls[0].newClientOrderId);

      const intent = db.prepare('SELECT * FROM order_intents WHERE client_order_id = ?').get(calls[0].newClientOrderId) as any;
      assert.ok(intent, 'intent must be journaled under the clientOrderId');
      assert.equal(intent.kind, 'entry');
      assert.equal(intent.side, 'BUY');
      assert.equal(intent.state, 'resolved', 'intent must resolve after the position is recorded');
      assert.equal(intent.exchange_order_id, '777');

      const pos = db.prepare("SELECT id FROM positions WHERE traded_currency = 'itstbuy' AND status = 'open'").get() as any;
      assert.ok(pos);
      cleanupPosition(pos.id);
    } finally {
      indodax.getAccountInfo = originalAccount;
      indodax.createOrder = originalCreate;
      indodax.waitForOrderFill = originalWait;
    }
  });

  test('reconcileUnresolvedIntents detects an order that FILLED while the process was down and halts', async () => {
    sealExistingIntents();
    setSetting('trading_mode', 'live');
    const id = `oi_test_${Date.now()}`;
    db.prepare(`
      INSERT INTO order_intents (id, ts, symbol, side, kind, order_type, params_json, client_order_id, state, exchange_order_id)
      VALUES (?, ?, 'testcoinidr', 'BUY', 'entry', 'MARKET', '{}', 'itdentest1', 'ack', '4242')
    `).run(id, Date.now() - 120_000);

    const originalLookup = indodax.getOrderByClientOrderId;
    indodax.getOrderByClientOrderId = (async () => ({
      status: 'FILLED', executedQty: '100', quoteQty: '100000', avgPrice: '1000',
    })) as any;

    try {
      const result = await engine.reconcileUnresolvedIntents(1000);
      assert.equal(result.requiresHalt, true, 'a filled-but-unrecorded order must halt auto-trading');
      assert.ok(result.issues.some((i) => i.includes('TERNYATA TERISI')));

      const row = db.prepare('SELECT state FROM order_intents WHERE id = ?').get(id) as any;
      assert.equal(row.state, 'resolved');
    } finally {
      indodax.getOrderByClientOrderId = originalLookup;
      db.prepare('DELETE FROM order_intents WHERE id = ?').run(id);
      setSetting('trading_mode', 'paper');
    }
  });

  test('reconcileUnresolvedIntents marks an order that never reached the exchange as unresolved without halting', async () => {
    sealExistingIntents();
    setSetting('trading_mode', 'live');
    const id = `oi_test_${Date.now()}`;
    db.prepare(`
      INSERT INTO order_intents (id, ts, symbol, side, kind, order_type, params_json, client_order_id, state)
      VALUES (?, ?, 'testcoinidr', 'SELL', 'exit', 'LIMIT', '{}', 'itdentest2', 'sent')
    `).run(id, Date.now() - 120_000);

    const originalLookup = indodax.getOrderByClientOrderId;
    indodax.getOrderByClientOrderId = (async () => ({})) as any; // unknown order

    try {
      const result = await engine.reconcileUnresolvedIntents(1000);
      assert.equal(result.requiresHalt, false);

      const row = db.prepare('SELECT state FROM order_intents WHERE id = ?').get(id) as any;
      assert.equal(row.state, 'unresolved');
    } finally {
      indodax.getOrderByClientOrderId = originalLookup;
      db.prepare('DELETE FROM order_intents WHERE id = ?').run(id);
      setSetting('trading_mode', 'paper');
    }
  });
});

// ---------------------------------------------------------------------------
// Drawdown kill switch end-to-end (through the daily breaker's equity read)
// ---------------------------------------------------------------------------

describe('Drawdown Kill Switch (end-to-end)', () => {
  const originalSnapshot = tradingEngine.getEquitySnapshot.bind(tradingEngine);

  test('halts on a 20% drawdown, de-risks by halving positions, and resets manually', async () => {
    const originalTradingMode = getSetting('trading_mode', 'paper');
    setSetting('trading_mode', 'live');
    setSetting('daily_loss_limit_percent', '100'); // isolate from the daily breaker
    setSetting('max_drawdown_percent', '15');
    setSetting('derisk_mode_on_drawdown', 'halve');
    setSetting('equity_peak_live', '1000000');
    setSetting('drawdown_halt_since', '0');
    setSetting('circuit_breaker_triggered_at', '0');
    setSetting('is_auto_trading_active', '1');

    const pos = insertLivePosition('ddhalve', 2, 100_000);
    const mock = mockExchange([{ type: 'LIMIT', executedQty: 1, price: 100_000 }]);

    // Equity fell to 800k from a 1M peak → 20% drawdown ≥ 15% limit
    tradingEngine.getEquitySnapshot = (async () => ({
      mode: 'live',
      cashIdr: 600_000,
      cashFreeIdr: 600_000,
      cashLockedIdr: 0,
      holdingsValueIdr: 200_000,
      equityIdr: 800_000,
      floatingPnlIdr: -200_000,
      openPositions: 1,
    })) as any;

    try {
      const blocked = await tradingEngine.checkDailyCircuitBreaker();
      assert.equal(blocked, true, 'drawdown breach must block new entries');

      assert.ok(parseInt(getSetting('drawdown_halt_since', '0'), 10) > 0, 'halt must be latched');
      assert.equal(getSetting('is_auto_trading_active'), '0', 'auto-trading must stop');

      const row = db.prepare('SELECT amount FROM positions WHERE id = ?').get(pos.id) as any;
      assert.equal(row.amount, 1, 'halve de-risk must sell 50% of the position');

      // Second evaluation is idempotent (no double de-risk)
      const callsAfterFirst = mock.calls.length;
      await tradingEngine.checkDailyCircuitBreaker();
      assert.equal(mock.calls.length, callsAfterFirst, 'latched halt must not re-run the de-risk');

      // Manual reset re-bases the peak to current equity
      const reset = await tradingEngine.resetDrawdownKillSwitch();
      assert.equal(reset.cleared, true);
      assert.equal(getSetting('drawdown_halt_since'), '0');
      assert.equal(getSetting('equity_peak_live'), '800000');
    } finally {
      tradingEngine.getEquitySnapshot = originalSnapshot;
      mock.restore();
      cleanupPosition(pos.id);
      setSetting('trading_mode', originalTradingMode);
      setSetting('daily_loss_limit_percent', '5');
      setSetting('derisk_mode_on_drawdown', 'halt');
      setSetting('equity_peak_live', '0');
      setSetting('equity_peak_paper', '0');
      setSetting('drawdown_halt_since', '0');
      setSetting('circuit_breaker_triggered_at', '0');
    }
  });

  test('does not trigger when equity is above the drawdown threshold', async () => {
    setSetting('max_drawdown_percent', '15');
    setSetting('equity_peak_live', '1000000');
    setSetting('drawdown_halt_since', '0');
    setSetting('circuit_breaker_triggered_at', '0');

    tradingEngine.getEquitySnapshot = (async () => ({
      mode: 'live',
      cashIdr: 900_000,
      cashFreeIdr: 900_000,
      cashLockedIdr: 0,
      holdingsValueIdr: 0,
      equityIdr: 900_000,
      floatingPnlIdr: 0,
      openPositions: 0,
    })) as any;

    try {
      const blocked = await tradingEngine.checkDailyCircuitBreaker();
      assert.equal(blocked, false);
      assert.equal(getSetting('drawdown_halt_since'), '0');
      assert.equal(getSetting('equity_peak_live'), '1000000', 'peak must not regress');
    } finally {
      tradingEngine.getEquitySnapshot = originalSnapshot;
      setSetting('equity_peak_live', '0');
    }
  });
});

import crypto from 'crypto';
import { db, getSetting, setSetting } from '../../db/index.js';

export interface IndodaxPair {
  id: string; // e.g. 'btcidr'
  symbol: string; // e.g. 'BTCIDR'
  base_currency: string; // e.g. 'idr'
  traded_currency: string; // e.g. 'btc'
  traded_currency_unit: string; // e.g. 'BTC'
  description: string;
  ticker_id: string;
  price_precision: number;
  trade_min_base_currency: number;
  trade_min_traded_currency: number;
  quantity_increment?: string | number;
  trade_fee_percent?: number;
  url_logo?: string;
  url_logo_png?: string;
}

export interface IndodaxSummaryTicker {
  name: string;
  last: string;
  high: string;
  low: string;
  vol_idr: string;
  vol_traded?: string;
  buy: string;
  sell: string;
  server_time: number;
}

export interface IndodaxDepth {
  buy: Array<[string, string]>; // [price, volume]
  sell: Array<[string, string]>;
}

export interface IndodaxOrderResponse {
  symbol: string;
  orderId: number | string;
  clientOrderId?: string;
  side: 'BUY' | 'SELL';
  type: 'LIMIT' | 'MARKET';
  price?: string;
  origQty?: string;
  executedQty?: string;
  fullOrderId?: string;
}

export interface IndodaxFillInfo {
  orderId: string;
  status: string;
  executedQty: number;
  quoteQty: number;
  averagePrice: number;
  verified: boolean;
  isFinal: boolean;
}

const FINAL_ORDER_STATUSES = new Set(['FILLED', 'CANCELED', 'CANCELLED', 'REJECTED', 'EXPIRED']);

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export class IndodaxClient {
  private publicBaseUrl = 'https://indodax.com';
  private tradeBaseUrl = 'https://api.indodax.com';
  private tapiBaseUrl = 'https://indodax.com/tapi';
  private knownPairIds: Set<string> = new Set();
  private pairsCache: Map<string, IndodaxPair> = new Map();
  private pairsCacheTime = 0;
  private pairsInFlight: Promise<IndodaxPair[]> | null = null;
  private summariesCache: { tickers: Record<string, IndodaxSummaryTicker>; prices_24h: Record<string, string> } | null = null;
  private summariesCacheTime = 0;
  private summariesInFlight: Promise<{ tickers: Record<string, IndodaxSummaryTicker>; prices_24h: Record<string, string> }> | null = null;
  private summariesTtlMs = 6000; // 6s TTL cache to avoid ~6,000 redundant requests/day

  private depthCache: Map<string, { data: IndodaxDepth; time: number }> = new Map();
  private depthTtlMs = 4000; // 4s TTL cache for orderbook depth

  private onNewCoinCallback?: (coin: { symbol: string; name: string; price: number; volume: number }) => void;

  constructor() {
    this.loadKnownPairs();
  }

  public setNewCoinCallback(cb: (coin: { symbol: string; name: string; price: number; volume: number }) => void) {
    this.onNewCoinCallback = cb;
  }

  private loadKnownPairs() {
    try {
      // Migrate legacy alert rows so an upgrade never re-announces old listings
      db.prepare(
        'INSERT OR IGNORE INTO known_pairs (pair_id, first_seen_at) SELECT LOWER(symbol), detected_at FROM new_coin_alerts'
      ).run();

      const rows = db.prepare('SELECT pair_id FROM known_pairs').all() as Array<{ pair_id: string }>;
      for (const row of rows) {
        this.knownPairIds.add(row.pair_id.toLowerCase());
      }
    } catch (err) {
      console.warn('[Indodax] Gagal memuat known pairs registry:', err instanceof Error ? err.message : err);
    }
  }

  // --- Public REST API Methods ---

  /**
   * Parse respon JSON secara aman dengan perlindungan terhadap halaman error HTML 502/504 Cloudflare
   */
  private async safeParseResponse<T = any>(res: Response, endpointName: string): Promise<T> {
    const rawText = await res.text();
    if (!res.ok) {
      const cleanSnippet = rawText.slice(0, 150).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      throw new Error(`Indodax ${endpointName} gagal (${res.status} ${res.statusText}): ${cleanSnippet || 'Gateway/Cloudflare error'}`);
    }
    try {
      return JSON.parse(rawText) as T;
    } catch {
      const cleanSnippet = rawText.slice(0, 150).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      throw new Error(`Indodax ${endpointName} mengembalikan non-JSON response (${res.status}): ${cleanSnippet || 'Invalid JSON format'}`);
    }
  }

  public async getPairs(forceRefresh = false): Promise<IndodaxPair[]> {
    const now = Date.now();
    if (!forceRefresh && this.pairsCache.size > 0 && now - this.pairsCacheTime < 10 * 60 * 1000) {
      return Array.from(this.pairsCache.values());
    }
    if (this.pairsInFlight) {
      return this.pairsInFlight;
    }

    this.pairsInFlight = this.fetchAndTrackPairs();
    try {
      return await this.pairsInFlight;
    } finally {
      this.pairsInFlight = null;
    }
  }

  private async fetchAndTrackPairs(): Promise<IndodaxPair[]> {
    const res = await fetch(`${this.publicBaseUrl}/api/pairs`);
    const pairs = await this.safeParseResponse<IndodaxPair[]>(res, 'getPairs');

    // Filter only IDR base currency pairs
    const idrPairs = pairs.filter(p => p.base_currency.toLowerCase() === 'idr');

    this.pairsCache.clear();
    for (const p of idrPairs) {
      this.pairsCache.set(p.id.toLowerCase(), p);
      this.pairsCache.set(p.symbol.toUpperCase(), p);
    }
    this.pairsCacheTime = Date.now();

    await this.trackPairUniverse(idrPairs);
    return idrPairs;
  }

  /**
   * Persists the full pair universe. The first run after install/upgrade seeds the
   * registry silently; later runs only raise alerts for pairs never seen before.
   */
  private async trackPairUniverse(idrPairs: IndodaxPair[]) {
    try {
      const seeded = getSetting('known_pairs_seeded', '0') === '1';
      const insertKnown = db.prepare(
        'INSERT OR IGNORE INTO known_pairs (pair_id, first_seen_at) VALUES (?, ?)'
      );
      const newPairs: IndodaxPair[] = [];
      const now = Date.now();

      for (const pair of idrPairs) {
        const id = pair.id.toLowerCase();
        insertKnown.run(id, now);
        if (seeded && !this.knownPairIds.has(id)) {
          newPairs.push(pair);
        }
        this.knownPairIds.add(id);
      }

      if (!seeded) {
        setSetting('known_pairs_seeded', '1');
        console.log(`[Indodax] Registry pair awal disimpan (${idrPairs.length} pair), tanpa alert massal.`);
        return;
      }

      for (const pair of newPairs) {
        let lastPrice = 0;
        let volume24h = 0;
        try {
          const { ticker } = await this.getTicker(pair.id);
          lastPrice = parseFloat(ticker?.last || '0') || 0;
          volume24h = parseFloat(ticker?.vol_idr || '0') || 0;
        } catch {
          // Alert still matters; price will be shown as unavailable
        }
        this.recordNewCoinListing(pair, lastPrice, volume24h);
      }
    } catch (err) {
      console.warn('[Indodax] Gagal memperbarui registry pair:', err instanceof Error ? err.message : err);
    }
  }

  public getPairRules(symbol: string): IndodaxPair | undefined {
    const clean = symbol.toLowerCase().replace('/', '').replace('_', '');
    return this.pairsCache.get(clean) || this.pairsCache.get(clean.toUpperCase());
  }

  public formatQuantity(symbol: string, rawQuantity: number): string {
    const pair = this.getPairRules(symbol);
    const increment = pair?.quantity_increment ? String(pair.quantity_increment) : '0.00000001';
    const decimals = increment.includes('.') ? increment.split('.')[1].length : 0;
    const factor = Math.pow(10, decimals);
    // Always floor to avoid exceeding available balance
    const floored = Math.floor(rawQuantity * factor) / factor;
    return floored.toFixed(decimals);
  }

  public getMinTradeIdr(symbol: string): number {
    const pair = this.getPairRules(symbol);
    return pair?.trade_min_base_currency || 10000;
  }

  public async getSummaries(force = false): Promise<{ tickers: Record<string, IndodaxSummaryTicker>; prices_24h: Record<string, string> }> {
    const now = Date.now();
    if (!force && this.summariesCache && now - this.summariesCacheTime < this.summariesTtlMs) {
      return this.summariesCache;
    }
    if (this.summariesInFlight) {
      return this.summariesInFlight;
    }

    this.summariesInFlight = (async () => {
      try {
        const res = await fetch(`${this.publicBaseUrl}/api/summaries`);
        const data = await this.safeParseResponse<{ tickers: Record<string, IndodaxSummaryTicker>; prices_24h: Record<string, string> }>(res, 'getSummaries');
        this.summariesCache = data;
        this.summariesCacheTime = Date.now();
        return data;
      } finally {
        this.summariesInFlight = null;
      }
    })();

    return this.summariesInFlight;
  }

  public async getDepth(pairId: string, force = false): Promise<IndodaxDepth> {
    let clean = pairId.toLowerCase().replace('/', '').replace('_', '');
    if (!clean.endsWith('idr') && !clean.endsWith('usdt')) {
      clean = `${clean}idr`;
    }
    const now = Date.now();
    const cached = this.depthCache.get(clean);
    if (!force && cached && now - cached.time < this.depthTtlMs) {
      return cached.data;
    }

    const res = await fetch(`${this.publicBaseUrl}/api/depth/${clean}`);
    const data = await this.safeParseResponse<IndodaxDepth>(res, `getDepth(${clean})`);
    this.depthCache.set(clean, { data, time: Date.now() });
    return data;
  }

  public async getTicker(pairId: string): Promise<{ ticker: IndodaxSummaryTicker }> {
    let clean = pairId.toLowerCase().replace('/', '').replace('_', '');
    if (!clean.endsWith('idr') && !clean.endsWith('usdt')) {
      clean = `${clean}idr`;
    }
    const res = await fetch(`${this.publicBaseUrl}/api/ticker/${clean}`);
    return await this.safeParseResponse<{ ticker: IndodaxSummaryTicker }>(res, `getTicker(${clean})`);
  }

  // --- Slippage & Liquidity Protection ---

  public calculateSlippage(
    depth: IndodaxDepth,
    side: 'buy' | 'sell',
    totalIdr: number
  ): { averageFillPrice: number; bestPrice: number; slippagePercent: number; isSufficientLiquidity: boolean } {
    const book = side === 'buy' ? depth.sell : depth.buy;
    if (!book || book.length === 0) {
      return { averageFillPrice: 0, bestPrice: 0, slippagePercent: 100, isSufficientLiquidity: false };
    }

    const bestPrice = parseFloat(book[0][0]);
    let remainingIdr = totalIdr;
    let totalSpentIdr = 0;
    let totalTradedCurrency = 0;

    for (const [priceStr, volStr] of book) {
      const price = parseFloat(priceStr);
      const volumeTraded = parseFloat(volStr);
      const orderVolumeIdr = price * volumeTraded;

      if (remainingIdr <= orderVolumeIdr) {
        const tradedAmount = remainingIdr / price;
        totalTradedCurrency += tradedAmount;
        totalSpentIdr += remainingIdr;
        remainingIdr = 0;
        break;
      } else {
        totalTradedCurrency += volumeTraded;
        totalSpentIdr += orderVolumeIdr;
        remainingIdr -= orderVolumeIdr;
      }
    }

    if (remainingIdr > 0) {
      return {
        averageFillPrice: totalSpentIdr / (totalTradedCurrency || 1),
        bestPrice,
        slippagePercent: 999,
        isSufficientLiquidity: false,
      };
    }

    const averageFillPrice = totalSpentIdr / totalTradedCurrency;
    const slippagePercent = Math.abs((averageFillPrice - bestPrice) / bestPrice) * 100;

    return {
      averageFillPrice,
      bestPrice,
      slippagePercent,
      isSufficientLiquidity: true,
    };
  }

  /**
   * Menghitung Bid-Ask Spread (%) untuk menghindari jebakan likuiditas tipis (spread trap).
   */
  public calculateSpread(depth: IndodaxDepth): { bestBid: number; bestAsk: number; spreadPercent: number } {
    const bestBid = depth.buy && depth.buy[0] ? parseFloat(depth.buy[0][0]) : 0;
    const bestAsk = depth.sell && depth.sell[0] ? parseFloat(depth.sell[0][0]) : 0;
    if (bestBid <= 0 || bestAsk <= 0) {
      return { bestBid, bestAsk, spreadPercent: 100 };
    }
    const spreadPercent = Math.abs((bestAsk - bestBid) / bestAsk) * 100;
    return { bestBid, bestAsk, spreadPercent: Number(spreadPercent.toFixed(2)) };
  }

  /**
   * Menghitung rasio dominasi volume Bid vs Ask (Depth Imbalance Ratio) pada 10 layer teratas.
   * Rasio > 1.0 menandakan dinding beli (buying wall) lebih tebal dari dinding jual.
   */
  public calculateDepthImbalance(depth: IndodaxDepth, layers: number = 10): number {
    const bids = (depth.buy || []).slice(0, layers);
    const asks = (depth.sell || []).slice(0, layers);
    const bidVolIdr = bids.reduce((acc, [p, v]) => acc + parseFloat(p) * parseFloat(v), 0);
    const askVolIdr = asks.reduce((acc, [p, v]) => acc + parseFloat(p) * parseFloat(v), 0);
    if (askVolIdr <= 0) return bidVolIdr > 0 ? 2.0 : 1.0;
    return Number((bidVolIdr / askVolIdr).toFixed(2));
  }

  // --- Official Private Trade API 2.0 (HMAC-SHA256) ---

  private getAuthCredentials(): { apiKey: string; secretKey: string } {
    const apiKey = getSetting('indodax_api_key', '');
    const secretKey = getSetting('indodax_secret_key', '');
    return { apiKey, secretKey };
  }

  private generateHmacSha256(data: string, secretKey: string): string {
    return crypto.createHmac('sha256', secretKey).update(data).digest('hex');
  }

  private static readonly MAX_PRIVATE_RETRIES = 3;

  private retryDelayMs(attempt: number, retryAfterHeader?: string | null): number {
    const retryAfter = parseFloat(retryAfterHeader || '0');
    if (Number.isFinite(retryAfter) && retryAfter > 0) {
      return Math.min(retryAfter * 1000, 15000);
    }
    // Exponential backoff with jitter: ~400ms, ~800ms, ~1600ms (+-25%)
    const base = 400 * Math.pow(2, attempt);
    const jitter = base * (0.75 + Math.random() * 0.5);
    return Math.min(Math.round(jitter), 8000);
  }

  /**
   * Sends a signed private request. GET/DELETE are retried on transient
   * failures (network error, 429, 5xx) with exponential backoff honoring
   * Retry-After. POST is NEVER retried blindly: createOrder is not idempotent
   * and a duplicate market order would double an entry — order intents cover
   * crash recovery for POSTs instead.
   */
  private async executePrivateRequest<T>(
    endpoint: string,
    method: 'GET' | 'POST' | 'DELETE',
    params: Record<string, string | number>,
    attempt = 0
  ): Promise<T> {
    const { apiKey, secretKey } = this.getAuthCredentials();
    if (!apiKey || !secretKey) {
      throw new Error('Indodax API Key / Secret Key belum dikonfigurasi di menu Settings.');
    }

    const timestamp = Date.now();
    const payload: Record<string, string | number> = {
      ...params,
      timestamp,
      recvWindow: 5000,
    };

    // Sort parameters alphabetically per TAPI v2 specification
    const sortedKeys = Object.keys(payload).sort();
    const queryString = sortedKeys.map(k => `${encodeURIComponent(k)}=${encodeURIComponent(payload[k])}`).join('&');
    const signature = this.generateHmacSha256(queryString, secretKey);

    const isGetOrDelete = method === 'GET' || method === 'DELETE';
    const url = `${this.tradeBaseUrl}${endpoint}${isGetOrDelete ? `?${queryString}&signature=${signature}` : ''}`;

    const headers: Record<string, string> = {
      Accept: 'application/json',
      'X-APIKEY': apiKey,
      Sign: signature,
    };

    if (method === 'POST') {
      headers['Content-Type'] = 'application/x-www-form-urlencoded';
    }

    const options: RequestInit = {
      method,
      headers,
    };

    if (method === 'POST') {
      options.body = queryString;
    }

    let res: Response;
    try {
      res = await fetch(url, options);
    } catch (err: any) {
      if (isGetOrDelete && attempt < IndodaxClient.MAX_PRIVATE_RETRIES) {
        await sleep(this.retryDelayMs(attempt));
        return this.executePrivateRequest<T>(endpoint, method, params, attempt + 1);
      }
      throw new Error(`Indodax Trade API network error (${endpoint}): ${err?.message || err}`);
    }

    if (!res.ok) {
      const retryable = res.status === 429 || res.status >= 500;
      if (retryable && isGetOrDelete && attempt < IndodaxClient.MAX_PRIVATE_RETRIES) {
        await sleep(this.retryDelayMs(attempt, res.headers.get('retry-after')));
        return this.executePrivateRequest<T>(endpoint, method, params, attempt + 1);
      }
      const rawText = await res.text().catch(() => '');
      const cleanSnippet = rawText.slice(0, 150).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      throw new Error(`Indodax Trade API gagal (${endpoint} ${res.status} ${res.statusText}): ${cleanSnippet || 'Gateway/Cloudflare error'}`);
    }

    const rawText = await res.text();
    let data: any;
    try {
      data = JSON.parse(rawText);
    } catch {
      const cleanSnippet = rawText.slice(0, 150).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      throw new Error(`Indodax Trade API mengembalikan non-JSON response (${endpoint} ${res.status}): ${cleanSnippet || 'Invalid JSON format'}`);
    }

    if (data && typeof data.code === 'number' && data.code < 0) {
      throw new Error(`Indodax Trade API error: ${data.msg || res.statusText} (code: ${data.code})`);
    }

    return data as T;
  }

  private async callPrivateApi<T>(
    endpoint: string,
    method: 'GET' | 'POST' | 'DELETE',
    params: Record<string, string | number> = {}
  ): Promise<T> {
    return this.executePrivateRequest<T>(endpoint, method, params);
  }

  // --- Official Endpoints per INDODAX-TradeAPI-2.md ---

  /**
   * GET /api/v2/account
   * Mengambil saldo akun (balances: [{ asset: 'IDR', free: '...', locked: '...' }])
   * Responses are deduplicated for 1s and concurrent calls share one request:
   * the engine reads the account every loop and per-tick paths read it too.
   */
  private accountCache: { data: any; time: number } | null = null;
  private accountInFlight: Promise<any> | null = null;

  public async getAccountInfo(): Promise<{
    canTrade: boolean;
    canWithdraw: boolean;
    accountType: string;
    balances: Array<{ asset: string; free: string; locked: string }>;
    data?: { balance: { idr: number } }; // backward compatibility
  }> {
    const now = Date.now();
    if (this.accountCache && now - this.accountCache.time < 1000) {
      return this.accountCache.data;
    }
    if (this.accountInFlight) {
      return this.accountInFlight;
    }

    this.accountInFlight = (async () => {
      try {
        const result = await this.callPrivateApi<any>('/api/v2/account', 'GET', {});

        // Compute IDR free balance for convenience
        let idrFree = 0;
        if (Array.isArray(result?.balances)) {
          const idrEntry = result.balances.find((b: any) => String(b.asset).toUpperCase() === 'IDR');
          if (idrEntry) idrFree = parseFloat(idrEntry.free) || 0;
        }

        // Attach backward-compatible helper field
        result.data = { balance: { idr: idrFree } };
        this.accountCache = { data: result, time: Date.now() };
        return result;
      } finally {
        this.accountInFlight = null;
      }
    })();

    return this.accountInFlight;
  }

  public async getIdrBalance(): Promise<{ free: number; locked: number; total: number }> {
    try {
      const acc = await this.getAccountInfo();
      if (Array.isArray(acc?.balances)) {
        const idrEntry = acc.balances.find((b: any) => String(b.asset).toUpperCase() === 'IDR');
        if (idrEntry) {
          const free = parseFloat(idrEntry.free) || 0;
          const locked = parseFloat(idrEntry.locked) || 0;
          return { free, locked, total: free + locked };
        }
      }
      return { free: 0, locked: 0, total: 0 };
    } catch {
      return { free: 0, locked: 0, total: 0 };
    }
  }

  /**
   * POST /api/v2/order
   * Membuat order baru spot trading sesuai spesifikasi resmi INDODAX Trade API v2.0
   * 
   * Rules:
   * - MARKET BUY: Wajib menggunakan `quoteOrderQty` (IDR), tanpa `price` dan tanpa `quantity`.
   * - MARKET SELL: Menggunakan `quantity` (koin), tanpa `price` dan tanpa `quoteOrderQty`.
   * - LIMIT: Menggunakan `price`, `quantity`, dan `timeInForce: 'GTC'`.
   */
  public async createOrder(options: {
    symbol: string;
    side: 'BUY' | 'SELL' | 'buy' | 'sell';
    type: 'MARKET' | 'LIMIT' | 'market' | 'limit';
    quoteOrderQty?: number; // Nominal IDR untuk MARKET BUY
    quantity?: number; // Jumlah koin untuk MARKET SELL atau LIMIT
    price?: number; // Harga satuan koin untuk LIMIT
    newClientOrderId?: string; // Client-defined idempotency key (alphanumeric _-, max 36)
  }): Promise<IndodaxOrderResponse & { order_id?: string }> {
    const upperSymbol = options.symbol.toUpperCase().replace('/', '').replace('_', '');
    const upperSide = options.side.toUpperCase() as 'BUY' | 'SELL';
    const upperType = options.type.toUpperCase() as 'MARKET' | 'LIMIT';

    const params: Record<string, string | number> = {
      symbol: upperSymbol,
      side: upperSide,
      type: upperType,
    };

    if (options.newClientOrderId) {
      // Official spec: alphanumeric + `_` + `-` only, max 36 characters
      params.newClientOrderId = String(options.newClientOrderId).replace(/[^A-Za-z0-9_-]/g, '').slice(0, 36);
    }

    if (upperType === 'MARKET') {
      if (upperSide === 'BUY') {
        if (!options.quoteOrderQty || options.quoteOrderQty <= 0) {
          throw new Error('MARKET BUY membutuhkan parameter quoteOrderQty (nominal IDR).');
        }
        // Round to whole rupiah
        params.quoteOrderQty = Math.floor(options.quoteOrderQty);
      } else {
        // MARKET SELL
        if (!options.quantity || options.quantity <= 0) {
          throw new Error('MARKET SELL membutuhkan parameter quantity (jumlah koin).');
        }
        params.quantity = this.formatQuantity(upperSymbol, options.quantity);
      }
    } else {
      // LIMIT order
      if (!options.price || options.price <= 0) throw new Error('LIMIT order membutuhkan harga (price).');
      if (!options.quantity || options.quantity <= 0) throw new Error('LIMIT order membutuhkan jumlah koin (quantity).');
      params.price = Math.floor(options.price);
      params.quantity = this.formatQuantity(upperSymbol, options.quantity);
      params.timeInForce = 'GTC';
    }

    const result = await this.callPrivateApi<any>('/api/v2/order', 'POST', params);

    // Normalize order response. Never fabricate a fake id: fall back to the
    // clientOrderId (traceable via the order-intent journal) instead of Date.now().
    const orderId = result.orderId || result.order_id || params.newClientOrderId || '';
    return {
      ...result,
      orderId,
      order_id: String(orderId), // For backward compatibility
      clientOrderId: result.clientOrderId || params.newClientOrderId || '',
    };
  }

