  }

  public refreshOpenSymbols() {
    try {
      const rows = db.prepare("SELECT symbol FROM positions WHERE status = 'open'").all() as Array<{ symbol: string }>;
      this.openSymbolsSet.clear();
      for (const row of rows) {
