export class MultiAgentSwarm {
  private isRunning = false;
  private isExecuting = false; // In-flight guard
  private lastContextHash = '';
  private intervalTimer: NodeJS.Timeout | null = null;
  private onAgentLogCallback?: (log: SubagentOutput) => void;

  constructor() {
    this.pruneOldLogs();
  }

  public setLogCallback(cb: (log: SubagentOutput) => void) {
    this.onAgentLogCallback = cb;
  }

  public start(intervalMs = 60000) {
    if (this.isRunning) return;
    this.isRunning = true;
    this.runCycle();
    this.intervalTimer = setInterval(() => this.runCycle(), intervalMs);
    console.log('[Multi-Agent Swarm] 10 subagent aktif dengan konteks terisolasi (RSS + data bursa Indodax).');
  }

  public stop() {
    this.isRunning = false;
    if (this.intervalTimer) {
      clearInterval(this.intervalTimer);
      this.intervalTimer = null;
    }
  }

  // Run all subagents concurrently, each with its own isolated prompt context
  public async runCycle(force = false) {
    if (this.isExecuting) return; // In-flight guard
    this.isExecuting = true;

    try {
      const subagentModel = getSetting('subagent_model', '');

      // Transparent: If user has not configured an AI provider model, do NOT spam fake hallucinations
      if (!subagentModel) {
        return;
      }

      // Fetch live real market data from Indodax to ground subagents in actual reality
      let liveSummaries: any = null;
      try {
        liveSummaries = await indodax.getSummaries();
      } catch {
        // Fallback if network blip
      }

      // Fetch live breaking news from CoinDesk, CoinTelegraph & Indodax Official Blog RSS (with 5m caching)
      const [coinDeskFeed, coinTelegraphFeed, indodaxBlogFeed] = await Promise.all([
        rssNewsService.getFeed('https://www.coindesk.com/arc/outboundfeeds/rss/', 5),
        rssNewsService.getFeed('https://cointelegraph.com/rss', 5),
        rssNewsService.getFeed('https://blog.indodax.com/feed/', 5),
      ]);
      const extraFeeds: NewsFeedContext[] = await Promise.all(
        getExtraFeedUrls().map(async (url) => ({
          source: feedSourceName(url),
          items: await rssNewsService.getFeed(url, 5),
        }))
      );

      const newsContext: SwarmNewsContext = {
        coinDesk: coinDeskFeed,
        coinTelegraph: coinTelegraphFeed,
        indodaxBlog: indodaxBlogFeed,
        extra: extraFeeds,
      };

      // Ingest news into news_items table with deterministic lexicon & threat analysis
      const allNews = [
        ...coinDeskFeed.map((n) => ({ ...n, source: 'CoinDesk' })),
        ...coinTelegraphFeed.map((n) => ({ ...n, source: 'CoinTelegraph' })),
        ...indodaxBlogFeed.map((n) => ({ ...n, source: 'Indodax Blog' })),
        ...extraFeeds.flatMap((feed) => feed.items.map((n) => ({ ...n, source: feed.source }))),
      ];

      for (const item of allNews) {
        try {
          const id = crypto.createHash('md5').update(`${item.source}:${item.title}`).digest('hex');
          const sentiment = scoreHeadline(item.title, item.description);
          const threats = detectThreats({
            id,
            source: item.source,
            title: item.title,
            description: item.description,
            fetchedAt: Date.now(),
          });
          const isThreat = threats.length > 0 ? 1 : 0;
          const threatSeverity = threats[0]?.severity || null;

          db.prepare(`
            INSERT INTO news_items (
              id, source, title, url, published_at, fetched_at, sentiment_score,
              matched_bullish, matched_bearish, mentioned_coins, is_threat, threat_severity
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(id) DO UPDATE SET
              fetched_at = excluded.fetched_at,
              sentiment_score = excluded.sentiment_score
          `).run(
            id,
            item.source,
            item.title,
            item.link || null,
            item.pubDate ? new Date(item.pubDate).getTime() : Date.now(),
            Date.now(),
            sentiment.score,
            JSON.stringify(sentiment.matchedBullish),
            JSON.stringify(sentiment.matchedBearish),
            JSON.stringify(sentiment.mentionedCoins),
            isThreat,
            threatSeverity
          );
        } catch {}
      }

      // Context Dedup: Check if market tickers and breaking news are identical to previous cycle
      const contextFingerprint = crypto
        .createHash('sha256')
        .update(
          JSON.stringify({
            d: coinDeskFeed.map((f) => f.title).slice(0, 5),
            t: coinTelegraphFeed.map((f) => f.title).slice(0, 5),
            b: indodaxBlogFeed.map((f) => f.title).slice(0, 3),
            x: extraFeeds.flatMap((feed) => feed.items.map((item) => item.title)).slice(0, 5),
            top: liveSummaries?.tickers
              ? Object.entries(liveSummaries.tickers)
                  .filter(([k]) => k.endsWith('_idr'))
                  .slice(0, 5)
                  .map(([k, v]: any) => `${k}:${v.last}`)
              : [],
          })
        )
        .digest('hex');

      const isEventDriven = getSetting('swarm_event_driven', '1') === '1';
      if (!force && isEventDriven && this.lastContextHash === contextFingerprint) {
        logAiCall('scout', subagentModel, 0, 0, 0, 'skipped_dedup');
        return;
      }
      this.lastContextHash = contextFingerprint;

      // Eksekusi subagents dalam batch kecil (2 agent per batch) dengan jeda 300ms
      // untuk mencegah burst rate limit (HTTP 429) pada Google Cloud Code
      const BATCH_SIZE = 2;
      for (let i = 0; i < SUBAGENT_DEFINITIONS.length; i += BATCH_SIZE) {
        const batch = SUBAGENT_DEFINITIONS.slice(i, i + BATCH_SIZE);
        await Promise.allSettled(
          batch.map(async (def) => {
            try {
              const output = await this.executeSubagent(def, subagentModel, liveSummaries, newsContext);
              if (output) {
                this.saveSubagentLog(output);
                if (this.onAgentLogCallback) {
                  this.onAgentLogCallback(output);
                }
              }
            } catch (err: any) {
              console.warn(`[Subagent ${def.name}] Gagal mengeksekusi cycle: ${err.message}`);
            }
          })
        );
        // Jeda ringan 300ms antar batch agar kuota per-menit aman
        if (i + BATCH_SIZE < SUBAGENT_DEFINITIONS.length) {
          await new Promise((resolve) => setTimeout(resolve, 300));
        }
      }
      this.pruneOldLogs();
    } finally {
      this.isExecuting = false;
    }
  }

  // Execute a single subagent with ISOLATED context
  private async executeSubagent(
    task: SubagentTask,
    model: string,
    liveSummaries: any,
    newsContext: SwarmNewsContext
  ): Promise<SubagentOutput | null> {
    const realContext = this.buildContextForAgent(task, liveSummaries, newsContext);

    const prompt = `Anda adalah sub-agent khusus: "${task.name}".
Tugas: ${task.role}
Sumber Data Aktual: ${realContext.source}
Sumber yang Tersedia untuk Tim: ${task.sources.join(', ')}

Konteks Data Pasar Terkini:
${JSON.stringify(realContext)}

Analisa secara objektif dan jujur. Gunakan HANYA data pada konteks di atas. Jangan mengklaim akses ke Twitter/X, Reddit, on-chain, atau sumber lain yang tidak ada di konteks. Jika data tidak tersedia, tulis "data tidak tersedia". Jangan membuat berita atau angka palsu.
Kembalikan HANYA format JSON valid berikut (tanpa markdown backtick):
{
  "title": "Judul ringkas temuan utama",
  "summary": "Analisa 2 kalimat mengenai dampak langsung ke harga crypto atau koin Indodax",
  "sentimentScore": 0.0, // Skor dari -1.0 (sangat panik/bearish/hack) sampai +1.0 (sangat bullish/pump)
  "coinsMentioned": ["BTC", "SOL", "PEPE"], // Simbol koin yang terpengaruh
  "isThreat": false // true jika ada hack, exploit, delisting, atau bahaya crash
}`;

    try {
      const responseText = await aiClient.complete({
        model,
        messages: [
          { role: 'system', content: 'Anda adalah AI financial market subagent. Jawab HANYA dalam JSON murni.' },
          { role: 'user', content: prompt },
        ],
        temperature: 0.2,
        agentCaller: 'scout',
      });

      // Clean JSON if wrapped in markdown
      let cleanJson = responseText.trim();
      if (cleanJson.startsWith('```json')) cleanJson = cleanJson.replace(/^```json/, '');
      if (cleanJson.startsWith('```')) cleanJson = cleanJson.replace(/^```/, '');
      if (cleanJson.endsWith('```')) cleanJson = cleanJson.replace(/```$/, '');
      cleanJson = cleanJson.trim();

      const parsed = JSON.parse(cleanJson);

      return {
        agentId: task.id,
        agentName: task.name,
        sourceName: typeof realContext.source === 'string' ? realContext.source : task.sources[0],
        title: parsed.title || `${task.name} Market Analysis`,
        summary: parsed.summary || 'Kondisi pasar normal tanpa anomali kritis.',
        sentimentScore: typeof parsed.sentimentScore === 'number' ? Math.max(-1, Math.min(1, parsed.sentimentScore)) : 0.0,
        coinsMentioned: Array.isArray(parsed.coinsMentioned) ? parsed.coinsMentioned : [],
        isThreat: Boolean(parsed.isThreat),
        timestamp: Date.now(),
      };
    } catch (err: any) {
      // Do NOT invent fake positive news if the AI model call failed
      return null;
    }
  }

  private saveSubagentLog(output: SubagentOutput) {
    try {
      const stmt = db.prepare(`
        INSERT INTO subagent_logs (id, agent_id, agent_name, source_name, title, summary, sentiment_score, coins_mentioned, is_threat, timestamp)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `);
      stmt.run(
        `log_${output.agentId}_${Date.now()}`,
        output.agentId,
        output.agentName,
        output.sourceName,
        output.title,
        output.summary,
        output.sentimentScore,
        JSON.stringify(output.coinsMentioned),
        output.isThreat ? 1 : 0,
        output.timestamp
      );
    } catch (err) {
      console.error('Error saving subagent log:', err);
    }
  }

  // Database Retention: Keep only the most recent 500 logs to prevent SQLite bloat
  public pruneOldLogs() {
    try {
      db.prepare(`
        DELETE FROM subagent_logs
        WHERE id NOT IN (
          SELECT id FROM subagent_logs
          ORDER BY timestamp DESC
          LIMIT 500
        )
      `).run();
    } catch (err) {
      // Ignore if table not yet initialized
    }
  }

  // Supplies real market data and telemetry to subagents
  private buildContextForAgent(
    task: SubagentTask,
    summaries: any,
    newsContext: SwarmNewsContext
  ): any {
    const time = new Date().toLocaleTimeString('id-ID');
    const tickers = summaries?.tickers || {};

    // Calculate real top gainers from live Indodax ticker data
    const gainers: Array<{ pair: string; last: string; gainPercent: number; volIdr: number }> = [];
    for (const [key, t] of Object.entries(tickers) as [string, any][]) {
      if (!key.endsWith('_idr')) continue;
      const low = parseFloat(t.low);
      const last = parseFloat(t.last);
      const volIdr = parseFloat(t.vol_idr);
      if (low > 0 && volIdr > 50000000) {
        const gain = ((last - low) / low) * 100;
        gainers.push({
          pair: key.replace('_idr', '').toUpperCase(),
          last: t.last,
          gainPercent: parseFloat(gain.toFixed(2)),
          volIdr,
        });
      }
    }
    gainers.sort((a, b) => b.gainPercent - a.gainPercent);
    const topGainers = gainers.slice(0, 5);

    // Top-of-book spreads from the public Indodax summaries feed
    const topLiquidity = (Object.entries(tickers) as [string, any][])
      .filter(([key]) => key.endsWith('_idr'))
      .map(([key, t]) => {
        const buy = parseFloat(t.buy);
        const sell = parseFloat(t.sell);
        const volIdr = parseFloat(t.vol_idr);
        return {
          pair: key.replace('_idr', '').toUpperCase(),
          bid: t.buy,
          ask: t.sell,
          spreadPercent: sell > 0 ? parseFloat((((sell - buy) / sell) * 100).toFixed(3)) : null,
          volIdr,
        };
      })
      .filter((row) => Number.isFinite(row.volIdr) && row.volIdr > 0)
      .sort((a, b) => b.volIdr - a.volIdr)
      .slice(0, 5);

    // Get recently detected new coin alerts
    let recentAlerts: any[] = [];
    try {
      recentAlerts = db.prepare('SELECT symbol, name, initial_price, current_price, detected_at FROM new_coin_alerts ORDER BY detected_at DESC LIMIT 3').all();
    } catch {}

    const allNewsHeadlines = [
      ...newsContext.coinDesk.map((i) => ({ source: 'CoinDesk', title: i.title })),
      ...newsContext.coinTelegraph.map((i) => ({ source: 'CoinTelegraph', title: i.title })),
      ...newsContext.indodaxBlog.map((i) => ({ source: 'Indodax Blog', title: i.title })),
      ...newsContext.extra.flatMap((feed) => feed.items.map((i) => ({ source: feed.source, title: i.title }))),
    ];
    const btcTicker = tickers.btc_idr;

    switch (task.id) {
      case 'subagent-1': // Global Crypto Breaking Wire
        return {
          source: 'CoinDesk RSS + CoinTelegraph RSS',
          time,
          realLiveHeadlines: allNewsHeadlines.slice(0, 8),
          btcPrice: btcTicker?.last || 'data tidak tersedia',
        };

      case 'subagent-2': // Tech & Ecosystem Analyst
        return {
          source: 'CoinDesk RSS + CoinTelegraph RSS',
          time,
          recentHeadlines: allNewsHeadlines.slice(0, 8),
          topMovers: topGainers.slice(0, 3),
        };

      case 'subagent-3': // News Sentiment Analyst
        return {
          source: 'CoinDesk/CoinTelegraph RSS + Lexicon Sentimen Deterministik + Indodax Tickers',
          time,
          headlineSentiments: allNewsHeadlines.slice(0, 6).map((news) => ({
            source: news.source,
            title: news.title,
            lexiconScore: scoreHeadline(news.title).score,
          })),
          btcPrice: btcTicker?.last || 'data tidak tersedia',
        };

      case 'subagent-4': // Market Narrative Radar
        return {
          source: 'CoinDesk/CoinTelegraph/Indodax Blog RSS + Indodax Market Tickers',
          time,
          latestHeadlines: allNewsHeadlines.slice(0, 10),
          topMovers: topGainers.slice(0, 5),
        };

      case 'subagent-7': {
        // Security & Exploit Radar (Strict regex: bare 'sec' is intentionally excluded to avoid false alarms)
        const securityNews = allNewsHeadlines.filter((n) =>
          /\b(hack|exploit|scam|stolen|drain|sec charges?|bappebti (block|ban|suspend)|arrest|lawsuit filed|attack|vulnerability|fraud)\b/i.test(n.title)
        );
        return {
          source: 'CoinDesk/CoinTelegraph RSS + Threat Scanner Deterministik',
          time,
          detectedIncidents:
            securityNews.length > 0
              ? securityNews
              : ['Tidak ada kata kunci hack/exploit/delisting pada headline RSS saat ini.'],
          note: 'Pemindaian ini hanya berbasis judul berita, bukan audit smart contract.',
        };
      }

      case 'subagent-5': // Indodax Listing Radar
        return {
          source: 'Indodax Blog RSS + Indodax New-Coin Alerts + Indodax Pairs API',
          time,
          officialAnnouncements: newsContext.indodaxBlog.map((n) => n.title),
          newListingAlerts: recentAlerts,
          activePairsCount: Object.keys(tickers).length,
        };

      case 'subagent-8': // Macro & Regulatory Radar
        return {
          source: 'CoinDesk/CoinTelegraph RSS + Indodax Blog RSS',
          time,
          domesticCryptoHeadlines: newsContext.indodaxBlog.map((n) => n.title),
          globalMacroHeadlines: [...newsContext.coinDesk, ...newsContext.coinTelegraph].slice(0, 6).map((n) => n.title),
          note: 'Tidak ada feed resmi The Fed, Bank Indonesia, atau Bappebti di konteks ini.',
        };

      case 'subagent-6': // Top Gainers & Momentum
        return {
          source: 'Indodax Market Tickers',
          time,
          topGainersToday: topGainers,
        };

      case 'subagent-9': // Liquidity & Spread Analyst
        return {
          source: 'Indodax Market Tickers (Top-of-Book)',
          time,
          topLiquidity,
        };

      case 'subagent-10': // BTC Correlation Analyst
        return {
          source: 'Indodax Market Tickers (BTC vs Altcoin)',
          time,
          btc24h: btcTicker
            ? { last: btcTicker.last, high: btcTicker.high, low: btcTicker.low, volIdr: btcTicker.vol_idr }
            : 'data tidak tersedia',
          topGainers: topGainers.slice(0, 5),
        };

      default:
        return {
          source: task.sources[0],
          time,
          marketSnapshot: {
            btcPrice: btcTicker?.last || 'data tidak tersedia',
            btc24hVolIdr: btcTicker?.vol_idr || '0',
            topMovers: topGainers.slice(0, 3),
          },
          latestHeadlines: allNewsHeadlines.slice(0, 3).map((n) => n.title),
        };
    }
  }

  // Calculate aggregated market sentiment and token sentiment map with Scoped Threat Detection (<30m freshness)
  public getAggregatedSentiment(): {
    averageSentiment: number;
    threatCount: number;
    coinSentiments: Record<string, number>;
    activeThreats: ThreatSignal[];
    threatenedCoins: Set<string>;
  } {
    const FRESH_MS = 30 * 60 * 1000; // 30-minute freshness window (P0-A requirement)
    const minTimestamp = Date.now() - FRESH_MS;

    const recentLogs = db.prepare(`
      SELECT sentiment_score, coins_mentioned, is_threat, timestamp
      FROM subagent_logs
      WHERE timestamp >= ?
      ORDER BY timestamp DESC
      LIMIT 50
    `).all(minTimestamp) as Array<{ sentiment_score: number; coins_mentioned: string; is_threat: number; timestamp: number }>;

    const activeThreats: ThreatSignal[] = [];
    const threatenedCoins = new Set<string>();

    for (const log of recentLogs) {
      if (log.is_threat) {
        let coins: string[] = [];
        try {
          coins = JSON.parse(log.coins_mentioned || '[]');
        } catch {}
        if (coins.length > 0) {
          for (const c of coins) {
            const upper = c.toUpperCase();
            threatenedCoins.add(upper);
            activeThreats.push({
              coin: upper,
              severity: 'high',
              matchedRule: 'subagent_flagged_threat',
              headline: 'Subagent Threat Telemetry',
              detectedAt: log.timestamp,
            });
          }
        } else {
          activeThreats.push({
            coin: null,
            severity: 'high',
            matchedRule: 'subagent_global_threat',
            headline: 'Global Subagent Threat Alert',
            detectedAt: log.timestamp,
          });
        }
      }
    }

    // Include fresh deterministic threats from news_items
    try {
      const newsThreats = db.prepare(`
        SELECT title, mentioned_coins, threat_severity, fetched_at
        FROM news_items
        WHERE is_threat = 1 AND fetched_at >= ?
        ORDER BY fetched_at DESC
        LIMIT 20
      `).all(minTimestamp) as Array<{ title: string; mentioned_coins: string; threat_severity: string; fetched_at: number }>;

      for (const nt of newsThreats) {
        let coins: string[] = [];
        try {
          coins = JSON.parse(nt.mentioned_coins || '[]');
        } catch {}
        if (coins.length > 0) {
          for (const c of coins) {
            const upper = c.toUpperCase();
            threatenedCoins.add(upper);
            activeThreats.push({
              coin: upper,
              severity: (nt.threat_severity as any) || 'medium',
              matchedRule: 'rule_based_threat',
              headline: nt.title,
              detectedAt: nt.fetched_at,
            });
          }
        } else {
          activeThreats.push({
            coin: null,
            severity: (nt.threat_severity as any) || 'high',
            matchedRule: 'rule_based_threat_global',
            headline: nt.title,
            detectedAt: nt.fetched_at,
          });
        }
      }
    } catch {}

    if (recentLogs.length === 0) {
      return {
        averageSentiment: 0,
        threatCount: activeThreats.length,
        coinSentiments: {},
        activeThreats,
        threatenedCoins,
      };
    }

    let totalScore = 0;
    const coinSentiments: Record<string, { total: number; count: number }> = {};

    for (const log of recentLogs) {
      totalScore += log.sentiment_score;
      try {
        const coins: string[] = JSON.parse(log.coins_mentioned || '[]');
        for (const coin of coins) {
          const upper = coin.toUpperCase();
          if (!coinSentiments[upper]) coinSentiments[upper] = { total: 0, count: 0 };
          coinSentiments[upper].total += log.sentiment_score;
          coinSentiments[upper].count += 1;
        }
      } catch {}
    }

    const normalizedCoinMap: Record<string, number> = {};
    for (const [coin, data] of Object.entries(coinSentiments)) {
      normalizedCoinMap[coin] = parseFloat((data.total / data.count).toFixed(2));
    }

    return {
      averageSentiment: parseFloat((totalScore / recentLogs.length).toFixed(2)),
      threatCount: activeThreats.length,
      coinSentiments: normalizedCoinMap,
      activeThreats,
      threatenedCoins,
    };
  }

  // --- AI Post-Mortem Reviewer (Self-Learning Memory) ---

  public async reviewClosedTrade(trade: {
    symbol: string;
    entryPrice: number;
    exitPrice: number;
    pnlPercent: number;
    holdDurationMinutes: number;
    exitReason: string;
  }) {
    const masterModel = getSetting('master_model', '');
    if (!masterModel) return; // Only review when a model is active

    const isWin = trade.pnlPercent >= 0;

    const prompt = `Lakukan evaluasi post-mortem objektif atas trade berikut:
Simbol: ${trade.symbol}
Harga Beli: ${trade.entryPrice}
Harga Jual: ${trade.exitPrice}
PnL: ${trade.pnlPercent.toFixed(2)}% (${isWin ? 'WIN / PROFIT' : 'LOSS / STOP LOSS'})
Durasi Hold: ${trade.holdDurationMinutes} menit
Alasan Exit: ${trade.exitReason}

Tuliskan 1 pelajaran penting (maksimal 2 kalimat) untuk memori trading AI agar di masa depan sistem ini dapat mengulangi kesuksesan atau mencegah kerugian pada kondisi serupa.`;

    try {
      const lesson = await aiClient.complete({
        model: masterModel,
        messages: [
          { role: 'system', content: 'Anda adalah Senior Quantitative Risk Manager. Berikan evaluasi ringkas dan aplikatif.' },
          { role: 'user', content: prompt },
        ],
        temperature: 0.3,
        max_tokens: 200,
        agentCaller: 'postmortem',
      });

      db.prepare(`
        INSERT INTO lessons_learned (id, trade_id, symbol, result, pnl_percent, market_condition, lesson, timestamp)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        `lesson_${Date.now()}`,
        `trade_${Date.now()}`,
        trade.symbol,
        isWin ? 'WIN' : 'LOSS',
        trade.pnlPercent,
        `Volatile / Momentum (${trade.holdDurationMinutes}m)`,
        lesson.trim(),
        Date.now()
      );
      console.log(`[AI Post-Mortem] Pelajaran disimpan untuk ${trade.symbol}: ${lesson.trim()}`);
    } catch (err: any) {
      console.warn('[AI Post-Mortem Reviewer] Gagal mereview trade:', err.message);
    }
  }
}

export const agentSwarm = new MultiAgentSwarm();

import { db, getSetting, logAiCall } from '../../db/index.js';
import {
  decryptProviderApiKeys,
  decryptProviderOAuth,
  encryptProviderOAuth,
} from '../security/secrets.js';
import {
  refreshAntigravityToken,
  callAntigravityChat,
  fetchLiveAntigravityModels,
  fetchAntigravityQuotas,
  AntigravityOAuthData,
  AntigravityQuotaReport,
  ANTIGRAVITY_STATIC_MODELS,
  ANTIGRAVITY_HEADERS,
} from '../antigravity/oauth.js';

export interface ChatMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface CompletionOptions {
  model?: string; // alias_model_id (e.g. "hrbr/deepseek-v3") or fallback
  messages: ChatMessage[];
  temperature?: number;
  max_tokens?: number;
  jsonMode?: boolean;
  agentCaller?: string; // 'scout' | 'analyst' | 'master' | 'postmortem' | 'whatsapp'
}

export interface ProviderRecord {
  id: string;
  name: string;
  base_url: string;
  api_keys: string; // JSON array of string
  alias: string;
  protocol: 'chat_completions' | 'messages' | 'antigravity';
  oauth_data?: string; // JSON string of AntigravityOAuthData
  is_active: number;
  created_at: number;
}

export interface ModelRecord {
  id: string;
  provider_id: string;
  model_id: string;
  alias_model_id: string;
  display_name: string;
  context_length: number;
  imported_at: number;
}

export class UniversalAIClient {
  private onEmergencyFailure?: (providerName: string, errorSummary: string) => Promise<void>;
  private static refreshPromises = new Map<string, Promise<{ accessToken: string; expiresAt: number }>>();
  private degradedMode = false;

  public isDegradedMode(): boolean {
    return this.degradedMode;
  }

  public setDegradedMode(val: boolean) {
    this.degradedMode = val;
  }

  public setEmergencyCallback(cb: (providerName: string, errorSummary: string) => Promise<void>) {
    this.onEmergencyFailure = cb;
  }

  // --- Import Models Automatically from Provider (e.g. Token Harbor) ---

  public async importModels(providerId: string): Promise<{ success: boolean; count: number; models: ModelRecord[]; message?: string }> {
    const provider = db.prepare('SELECT * FROM providers WHERE id = ?').get(providerId) as ProviderRecord | undefined;
    if (!provider) {
      throw new Error(`Provider dengan ID ${providerId} tidak ditemukan.`);
    }

    let fetchedModels: Array<{ id: string; name?: string; context_window?: number }> = [];

    // 1. Penanganan Khusus untuk Antigravity (Google Cloud Code OAuth)
    if (
      provider.protocol === 'antigravity' ||
      provider.alias.toLowerCase().startsWith('agy') ||
      provider.name.toLowerCase().includes('antigravity') ||
      provider.base_url.includes('cloudcode-pa')
    ) {
      let oauthData: AntigravityOAuthData | null = null;
      if (provider.oauth_data) {
        try {
          oauthData = decryptProviderOAuth<AntigravityOAuthData>(provider.oauth_data);
          // Auto-refresh jika token mendekati waktu kedaluwarsa (kurang dari 5 menit)
          if (oauthData && oauthData.refreshToken && Date.now() > (oauthData.expiresAt || 0) - 5 * 60 * 1000) {
            console.log(`[importModels] Auto-refreshing Antigravity token for ${provider.name}...`);
            const refreshed = await refreshAntigravityToken(oauthData.refreshToken);
            oauthData.accessToken = refreshed.accessToken;
            oauthData.expiresAt = refreshed.expiresAt;
            db.prepare('UPDATE providers SET oauth_data = ? WHERE id = ?').run(
              encryptProviderOAuth(oauthData),
              provider.id
            );
          }
        } catch (refErr) {
          console.warn('[importModels] Gagal refresh token Antigravity:', refErr);
        }
      }

      if (oauthData && oauthData.accessToken) {
        try {
          console.log(`[importModels] Mengambil model Antigravity real-time untuk ${provider.name}...`);
          const liveModels = await fetchLiveAntigravityModels(oauthData.accessToken, oauthData.projectId);
          if (liveModels.length > 0) {
            fetchedModels = liveModels;
          }
        } catch (discErr) {
          console.warn('[importModels] Dynamic models discovery threw error, fallback ke static catalog:', discErr);
        }
      }

      // Fallback ke static catalog jika fetch gagal
      if (fetchedModels.length === 0) {
        fetchedModels = ANTIGRAVITY_STATIC_MODELS.map((m) => ({
          id: m.id,
          name: `${m.name} (Antigravity)`,
          context_window: m.context_window,
        }));
      }
    } else {
      // 2. Penanganan Standar untuk Custom Provider (OpenAI, Token Harbor, Anthropic, dll)
      const apiKeys = decryptProviderApiKeys(provider.api_keys);
      if (apiKeys.length === 0 || !apiKeys[0]) {
        throw new Error(`Provider [${provider.name}] belum memiliki API Key. Harap isi minimal satu API Key.`);
      }

      // Normalize Base URL to reach the models endpoint
      let baseUrl = provider.base_url.trim();
      if (baseUrl.endsWith('/chat/completions')) {
        baseUrl = baseUrl.replace('/chat/completions', '');
      } else if (baseUrl.endsWith('/messages')) {
        baseUrl = baseUrl.replace('/messages', '');
      }
      if (baseUrl.endsWith('/')) {
        baseUrl = baseUrl.slice(0, -1);
      }

      let modelsEndpoint = `${baseUrl}/models`;
      if (!baseUrl.includes('/v1') && !baseUrl.includes('/v2')) {
        modelsEndpoint = `${baseUrl}/v1/models`;
      }

      let lastError = '';

      // Attempt import with each available key until one succeeds
      for (let i = 0; i < apiKeys.length; i++) {
        const key = apiKeys[i];
        try {
          const res = await fetch(modelsEndpoint, {
            method: 'GET',
            headers: {
              Authorization: `Bearer ${key}`,
              'Content-Type': 'application/json',
            },
          });

          if (!res.ok) {
            const errText = await res.text();
            throw new Error(`HTTP ${res.status}: ${errText}`);
          }

          const data = (await res.json()) as any;
          const rawList = Array.isArray(data) ? data : data.data || data.models || [];

          if (Array.isArray(rawList) && rawList.length > 0) {
            fetchedModels = rawList
              .map((m: any) => ({
                id: typeof m === 'string' ? m : m.id || m.model || m.name,
                name: typeof m === 'object' ? m.name || m.id : m,
                context_window: typeof m === 'object' ? m.context_window || m.context_length || 128000 : 128000,
              }))
              .filter((m) => !!m.id);
            break; // Key succeeded!
          }
        } catch (err: any) {
          lastError = `Key #${i + 1} failed: ${err.message}`;
        }
      }

      if (fetchedModels.length === 0) {
        // Fallback: If the provider doesn't support GET /models endpoint, register common flagship models
        fetchedModels = [
          { id: 'deepseek-v3', name: 'DeepSeek V3 (Chat)', context_window: 128000 },
          { id: 'deepseek-r1', name: 'DeepSeek R1 (Reasoning)', context_window: 128000 },
          { id: 'claude-3-7-sonnet', name: 'Claude 3.7 Sonnet', context_window: 200000 },
          { id: 'gpt-4o', name: 'GPT-4o', context_window: 128000 },
          { id: 'gpt-4o-mini', name: 'GPT-4o Mini', context_window: 128000 },
        ];
      }
    }

    // Insert or replace into SQLite models table
    const insertStmt = db.prepare(`
      INSERT INTO models (id, provider_id, model_id, alias_model_id, display_name, context_length, imported_at)
      VALUES (?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(alias_model_id) DO UPDATE SET
        display_name = excluded.display_name,
        context_length = excluded.context_length,
        imported_at = excluded.imported_at
    `);

    const now = Date.now();
    for (const m of fetchedModels) {
      const aliasModelId = `${provider.alias}/${m.id}`;
      insertStmt.run(
        `model_${provider.alias}_${m.id}`,
        provider.id,
        m.id,
        aliasModelId,
        m.name || m.id,
        m.context_window || 128000,
        now
      );
    }

    const savedModels = db.prepare('SELECT * FROM models WHERE provider_id = ?').all(provider.id) as ModelRecord[];

    return {
      success: true,
      count: savedModels.length,
      models: savedModels,
      message: `Berhasil mengimpor ${savedModels.length} model untuk provider ${provider.name}.`,
    };
  }

  // --- Unified Chat Completion with Auto-Failover across Multiple API Keys & Antigravity ---

  public async complete(options: CompletionOptions): Promise<string> {
    const aliasModelId = options.model || getSetting('master_model', '');
    const caller = options.agentCaller || 'master';
    const promptChars = options.messages.reduce((acc, m) => acc + (m.content ? m.content.length : 0), 0);
    const estInputTokens = Math.max(1, Math.ceil(promptChars / 4));
    const startTime = Date.now();

    // Resolve Model and Provider
    let modelRecord = db.prepare('SELECT * FROM models WHERE alias_model_id = ?').get(aliasModelId) as ModelRecord | undefined;
    let provider: ProviderRecord | undefined;

    if (modelRecord) {
      provider = db.prepare('SELECT * FROM providers WHERE id = ?').get(modelRecord.provider_id) as ProviderRecord | undefined;
    }

    // If specific model not configured, pick the first active provider and its first model
    if (!provider) {
      provider = db.prepare('SELECT * FROM providers WHERE is_active = 1 LIMIT 1').get() as ProviderRecord | undefined;
      if (!provider) {
        logAiCall(caller, aliasModelId, estInputTokens, 0, Date.now() - startTime, 'error');
        throw new Error('Belum ada AI Provider yang aktif. Silakan tambahkan di menu Settings > AI Providers.');
      }
      modelRecord = db.prepare('SELECT * FROM models WHERE provider_id = ? LIMIT 1').get(provider.id) as ModelRecord | undefined;
    }

    const rawModelId = modelRecord ? modelRecord.model_id : 'gpt-4o-mini';

    try {
      let result = '';
      if (provider.protocol === 'antigravity') {
        result = await this.callAntigravity(provider, rawModelId, options);
      } else {
        result = await this.executeWithFailover(provider, rawModelId, options);
      }

      this.degradedMode = false;
      const estOutputTokens = Math.max(1, Math.ceil(result.length / 4));
      logAiCall(caller, `${provider.alias}/${rawModelId}`, estInputTokens, estOutputTokens, Date.now() - startTime, 'ok');
      return result;
    } catch (err: any) {
      this.degradedMode = true;
      logAiCall(caller, `${provider?.alias || 'unknown'}/${rawModelId}`, estInputTokens, 0, Date.now() - startTime, 'error');
      throw err;
    }
  }

  private async executeWithFailover(
    provider: ProviderRecord,
    rawModelId: string,
    options: CompletionOptions
  ): Promise<string> {
    const apiKeys = decryptProviderApiKeys(provider.api_keys);

    if (apiKeys.length === 0) {
      throw new Error(`Provider [${provider.name}] tidak memiliki API Key yang valid.`);
    }

    let completionResult: string | null = null;
    const errors: string[] = [];

    // Auto-Failover: Iterate through API keys sequentially
    for (let i = 0; i < apiKeys.length; i++) {
      const apiKey = apiKeys[i].trim();
      if (!apiKey) continue;

      try {
        if (provider.protocol === 'messages') {
          completionResult = await this.callAnthropicMessages(provider, apiKey, rawModelId, options);
        } else {
          completionResult = await this.callOpenAIChat(provider, apiKey, rawModelId, options);
        }

        if (completionResult !== null) {
          return completionResult; // Successfully completed!
        }
      } catch (err: any) {
        const errorMsg = `Key #${i + 1}: ${err.message}`;
        console.warn(`[AI Failover] ${errorMsg}. Mencoba API Key berikutnya...`);
        errors.push(errorMsg);
      }
    }

    // IF ALL API KEYS FAILED:
    const summary = `Semua (${apiKeys.length}) API Key untuk provider [${provider.name}] gagal!\nDetail:\n${errors.join('\n')}`;
    console.error(`[CRITICAL AI FAILURE] ${summary}`);

    // Trigger WhatsApp Emergency Notification
    if (this.onEmergencyFailure) {
      try {
        await this.onEmergencyFailure(provider.name, summary);
      } catch (notifErr) {
        console.error('Gagal mengirim WhatsApp alert:', notifErr);
      }
    }

    throw new Error(`[AI Key Exhaustion] ${summary}`);
  }

  // --- OpenAI Compatible Chat Completions (`/v1/chat/completions`) ---

  private async callOpenAIChat(
    provider: ProviderRecord,
    apiKey: string,
    rawModelId: string,
    options: CompletionOptions
  ): Promise<string> {
    let url = provider.base_url.trim();
    if (!url.endsWith('/chat/completions')) {
      if (url.endsWith('/')) url = url.slice(0, -1);
      url = `${url}/chat/completions`;
    }

    const body: Record<string, any> = {
      model: rawModelId,
      messages: options.messages,
      temperature: options.temperature ?? 0.3,
      max_tokens: options.max_tokens ?? 2048,
    };

    if (options.jsonMode) {
      body.response_format = { type: 'json_object' };
    }

    const res = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify(body),
    });

    if (!res.ok) {
      const text = await res.text();
      throw new Error(`HTTP ${res.status}: ${text}`);
    }

    const data = (await res.json()) as any;
    const content = data.choices?.[0]?.message?.content;
    if (typeof content !== 'string') {
      throw new Error('Response format tidak valid dari provider (choices[0].message.content kosong).');
    }

    return content;
  }

  // --- Anthropic Compatible Messages (`/v1/messages`) ---

  private async callAnthropicMessages(
    provider: ProviderRecord,
    apiKey: string,
    rawModelId: string,
    options: CompletionOptions
  ): Promise<string> {
    let url = provider.base_url.trim();
    if (!url.endsWith('/messages')) {
      if (url.endsWith('/')) url = url.slice(0, -1);
      url = `${url}/messages`;
    }

    const systemMessage = options.messages.find(m => m.role === 'system')?.content || '';
    const nonSystemMessages = options.messages
      .filter(m => m.role !== 'system')
      .map(m => ({ role: m.role, content: m.content }));

    const body: Record<string, any> = {
      model: rawModelId,
      messages: nonSystemMessages,
      max_tokens: options.max_tokens ?? 2048,
      temperature: options.temperature ?? 0.3,
    };

    if (systemMessage) {
      body.system = systemMessage;
    }

    const res = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
      },
      body: JSON.stringify(body),
    });

    if (!res.ok) {
      const text = await res.text();
      throw new Error(`HTTP ${res.status}: ${text}`);
    }

    const data = (await res.json()) as any;
    const textBlock = data.content?.find((c: any) => c.type === 'text');
    return textBlock ? textBlock.text : '';
  }

  // --- Antigravity Google Cloud Code Integration with Auto-Token Refresh & Multi-Account Failover ---

  private async executeAntigravityWithSingleProvider(
    provider: ProviderRecord,
    rawModelId: string,
    options: CompletionOptions
  ): Promise<string> {
    let oauthData = decryptProviderOAuth<AntigravityOAuthData>(provider.oauth_data);
    if (!oauthData) {
      throw new Error(`Provider Antigravity [${provider.name}] belum terhubung melalui Google OAuth.`);
    }

    // Refresh token jika mendekati waktu habis (kurang dari 5 menit)
    if (Date.now() > (oauthData.expiresAt || 0) - 5 * 60 * 1000) {
      if (oauthData.refreshToken) {
        try {
          let refreshPromise = UniversalAIClient.refreshPromises.get(provider.id);
          if (!refreshPromise) {
            console.log(`[Antigravity] Access token untuk [${provider.name}] mendekati kedaluwarsa. Melakukan auto-refresh token...`);
            refreshPromise = refreshAntigravityToken(oauthData.refreshToken).finally(() => {
              UniversalAIClient.refreshPromises.delete(provider.id);
            });
            UniversalAIClient.refreshPromises.set(provider.id, refreshPromise);
          }
          const refreshed = await refreshPromise;
          oauthData = {
            ...oauthData,
            accessToken: refreshed.accessToken,
            expiresAt: refreshed.expiresAt,
          };
          db.prepare('UPDATE providers SET oauth_data = ? WHERE id = ?').run(
            encryptProviderOAuth(oauthData),
            provider.id
          );
        } catch (refErr: any) {
          console.warn(`[Antigravity] Auto-refresh gagal untuk [${provider.name}], mencoba menggunakan token yang ada:`, refErr.message);
        }
      }
    }

    try {
      return await callAntigravityChat({
        accessToken: oauthData.accessToken,
        projectId: oauthData.projectId,
        model: rawModelId,
        messages: options.messages,
        temperature: options.temperature,
        maxTokens: options.max_tokens,
      });
    } catch (err: any) {
      // Jika terjadi error 401 Unauthorized, coba refresh token darurat sekali lagi
      if (err.message && err.message.includes('401') && oauthData.refreshToken) {
        console.warn(`[Antigravity] HTTP 401 terdeteksi untuk [${provider.name}]. Melakukan refresh token darurat dan retry...`);
        const refreshed = await refreshAntigravityToken(oauthData.refreshToken);
        oauthData = {
          ...oauthData,
          accessToken: refreshed.accessToken,
          expiresAt: refreshed.expiresAt,
        };
        db.prepare('UPDATE providers SET oauth_data = ? WHERE id = ?').run(
          encryptProviderOAuth(oauthData),
          provider.id
        );
        return await callAntigravityChat({
          accessToken: oauthData.accessToken,
          projectId: oauthData.projectId,
          model: rawModelId,
          messages: options.messages,
          temperature: options.temperature,
          maxTokens: options.max_tokens,
        });
      }
      throw err;
    }
  }

  private static antigravityRoundRobinCounter = 0;

  private async callAntigravity(
    initialProvider: ProviderRecord,
    rawModelId: string,
    options: CompletionOptions
  ): Promise<string> {
    // 1. Ambil seluruh akun Antigravity aktif di database
    const allAgyProviders = db
      .prepare("SELECT * FROM providers WHERE protocol = 'antigravity' AND is_active = 1")
      .all() as ProviderRecord[];

    // 2. Tentukan urutan akun (Round-Robin Multi-Account load balancing)
    let providersToTry: ProviderRecord[] = [initialProvider];
    const otherProviders = allAgyProviders.filter((p) => p.id !== initialProvider.id);

    if (otherProviders.length > 0) {
      UniversalAIClient.antigravityRoundRobinCounter++;
      // Distribusikan beban 50/50 secara bergantian ke seluruh akun yang terhubung
      if (UniversalAIClient.antigravityRoundRobinCounter % (otherProviders.length + 1) !== 0) {
        providersToTry = [...otherProviders, initialProvider];
      } else {
        providersToTry = [initialProvider, ...otherProviders];
      }
    }

    let lastError: any = null;
    for (let i = 0; i < providersToTry.length; i++) {
      const prov = providersToTry[i];
      try {
        return await this.executeAntigravityWithSingleProvider(prov, rawModelId, options);
      } catch (err: any) {
        lastError = err;
        const nextProv = providersToTry[i + 1];
        if (nextProv) {
          console.warn(
            `[Antigravity Account Failover] Akun [${prov.name}] terkena limit/kendala (${err.message}). Otomatis beralih ke akun cadangan [${nextProv.name}]...`
          );
        }
      }
    }

    // Jika seluruh akun gagal, lempar error asli
    throw lastError || new Error(`Seluruh (${providersToTry.length}) akun Antigravity gagal merespons.`);
  }

  // --- Provider Quota Telemetry (Antigravity & OmniRoute /dashboard/quota compatibility) ---

  public async getProviderQuota(providerId: string): Promise<AntigravityQuotaReport> {
    const provider = db.prepare('SELECT * FROM providers WHERE id = ?').get(providerId) as ProviderRecord | undefined;
    if (!provider) {
      throw new Error(`Provider dengan ID ${providerId} tidak ditemukan.`);
    }

    let oauthData = decryptProviderOAuth<AntigravityOAuthData>(provider.oauth_data);
    if (!oauthData) {
      throw new Error(`Provider [${provider.name}] tidak memiliki konfigurasi Google OAuth.`);
    }

    // Auto-refresh token jika mendekati waktu kedaluwarsa
    if (oauthData.refreshToken && Date.now() > (oauthData.expiresAt || 0) - 5 * 60 * 1000) {
      try {
        const refreshed = await refreshAntigravityToken(oauthData.refreshToken);
        oauthData = {
          ...oauthData,
          accessToken: refreshed.accessToken,
          expiresAt: refreshed.expiresAt,
        };
        db.prepare('UPDATE providers SET oauth_data = ? WHERE id = ?').run(
          encryptProviderOAuth(oauthData),
          provider.id
        );
      } catch (err: any) {
        console.warn('[getProviderQuota] Token refresh notice:', err.message);
      }
    }

    const { groups, models } = await fetchAntigravityQuotas(oauthData.accessToken, oauthData.projectId);

    return {
      providerId: provider.id,
      providerName: provider.name,
      email: oauthData.email || 'Google User',
      projectId: oauthData.projectId || 'Default Project',
      alias: provider.alias,
      updatedAt: Date.now(),
      totalModels: models.length,
      groups,
      models,
    };
  }

  public async getAllAntigravityQuotas(): Promise<AntigravityQuotaReport[]> {
    const providers = db.prepare("SELECT * FROM providers WHERE protocol = 'antigravity' AND is_active = 1").all() as ProviderRecord[];
    const reports: AntigravityQuotaReport[] = [];

    for (const p of providers) {
      try {
        const report = await this.getProviderQuota(p.id);
        reports.push(report);
      } catch (err: any) {
        console.warn(`[getAllAntigravityQuotas] Gagal mengambil kuota untuk ${p.name}:`, err.message);
      }
    }

    return reports;
  }
}

