// Helper to decode runtime client identifiers
function unpackClientValue(hex: string, key = 0x5a): string {
  const bytes = hex.match(/.{2}/g) || [];
  return bytes.map((h) => String.fromCharCode(parseInt(h, 16) ^ key)).join('');
}

